import{_ as t,o as r,c as a,aw as i}from"./chunks/framework.DLufY-ao.js";const p=JSON.parse('{"title":"DRY","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/theory/refactoring/best-practices/dry.md","filePath":"wiki/dev-commit/theory/refactoring/best-practices/dry.md"}'),o={name:"wiki/dev-commit/theory/refactoring/best-practices/dry.md"};function c(s,e,l,n,d,_){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="dry" tabindex="-1">DRY <a class="header-anchor" href="#dry" aria-label="Permalink to &quot;DRY&quot;">​</a></h1><h2 id="информация" tabindex="-1">Информация <a class="header-anchor" href="#информация" aria-label="Permalink to &quot;Информация&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Определение</p><ul><li><strong>DRY</strong> (Don’t Repeat Yourself. Не повторяйся) - нацелен на снижение повторения информации различного рода, особенно в системах со множеством слоёв абстрагирования</li><li>Формулируется как: «Каждая часть знания должна иметь единственное, непротиворечивое и авторитетное представление в рамках системы»</li><li>Когда принцип DRY применяется успешно, изменение единственного элемента системы не требует внесения изменений в другие, логически не связанные элементы. Те элементы, которые логически связаны, изменяются предсказуемо и единообразно</li><li>Нарушения принципа DRY называют WET - «Write Everything Twice» (Пиши всё по два раза) или «We enjoy typing» (Нам нравится печатать)</li></ul></div>',3)])])}const h=t(o,[["render",c]]);export{p as __pageData,h as default};
